package com.ug.smartcampus.algorithm.graph;

import com.ug.smartcampus.datastructures.graph.Graph;import java.util.*;public final class Dijkstra{private Dijkstra(){}public static<T>Map<T,Double> shortestDistances(Graph<T>g,T start){Map<T,Double>d=new HashMap<>();for(T v:g.vertices())d.put(v,Double.POSITIVE_INFINITY);if(!d.containsKey(start))return d;d.put(start,0.0);PriorityQueue<Map.Entry<T,Double>>q=new PriorityQueue<>(Comparator.comparingDouble(Map.Entry::getValue));q.add(Map.entry(start,0.0));while(!q.isEmpty()){var e=q.poll();if(e.getValue()>d.get(e.getKey()))continue;for(var n:g.neighbors(e.getKey()).entrySet()){double nd=e.getValue()+n.getValue();if(nd<d.get(n.getKey())){d.put(n.getKey(),nd);q.add(Map.entry(n.getKey(),nd));}}}return d;}public static<T>List<T> shortestPath(Graph<T>g,T start,T goal){Map<T,T>prev=new HashMap<>();Map<T,Double>d=new HashMap<>();for(T v:g.vertices())d.put(v,Double.POSITIVE_INFINITY);d.put(start,0.0);PriorityQueue<T>q=new PriorityQueue<>(Comparator.comparingDouble(d::get));q.add(start);while(!q.isEmpty()){T v=q.poll();if(v.equals(goal))break;for(var n:g.neighbors(v).entrySet()){double nd=d.get(v)+n.getValue();if(nd<d.get(n.getKey())){d.put(n.getKey(),nd);prev.put(n.getKey(),v);q.remove(n.getKey());q.add(n.getKey());}}}if(!start.equals(goal)&&!prev.containsKey(goal))return List.of();LinkedList<T>path=new LinkedList<>();for(T v=goal;v!=null;v=prev.get(v))path.addFirst(v);return path;}}
